// The public-domain book the built-in sample takes apart (docs/sample-project.md):
// Jane Austen's Pride and Prejudice, 61 chapters in continuous numbering, and
// a few of Hugh Thomson's 1894 illustrations. The files under
// ./pride-and-prejudice/ are generated by scripts/build-sample-book.py.
//
// text.json encodes each chapter as blocks: a string is one paragraph, an
// array of strings is a letter set off as a block quote. Inside a paragraph,
// *…* marks italics and \n a line break; the text has no other markup.

import bookText from './pride-and-prejudice/text.json';
import bookManifest from './pride-and-prejudice/manifest.json';

export type BookBlock = string | readonly string[];

export interface BookChapter {
  number: number;
  roman: string;
  blocks: readonly BookBlock[];
}

export interface BookIllustration {
  name: string;
  title: string;
  /** The chapter the plate faces in the 1894 edition. */
  chapter: number;
  use: 'material' | 'portrait';
  kind: 'image';
  mime: 'image/jpeg';
  source: string;
  sha256: string;
  sizeBytes: number;
  width: number;
  height: number;
  variants: Record<'display' | 'thumbnail', { file: string; sha256: string }>;
}

export const BOOK_CHAPTERS = (bookText as { chapters: BookChapter[] }).chapters;
export const BOOK_ILLUSTRATIONS = bookManifest.illustrations as BookIllustration[];
export const BOOK_TEXT_SHA256 = bookManifest.text.sha256;

export function bookChapter(number: number): BookChapter {
  const chapter = BOOK_CHAPTERS[number - 1];
  if (!chapter || chapter.number !== number) throw new Error(`The sample book has no chapter ${number}`);
  return chapter;
}

/** Roman numerals as the edition prints them: 1 → I, 61 → LXI. */
export function chapterTitle(number: number): string {
  return `Chapter ${bookChapter(number).roman}`;
}

type ProseNode = Record<string, unknown>;

/** Splits text into runs, each naming the element id it links to, if any. */
export type EntityLinker = (text: string) => { text: string; elementId: string | null }[];

/**
 * A linker for the given forms (form → element id, or null for a form that
 * stays unlinked): whole words, case-sensitive, longest form first.
 */
export function createEntityLinker(forms: ReadonlyMap<string, string | null>): EntityLinker {
  const escaped = [...forms.keys()]
    .sort((left, right) => right.length - left.length)
    .map((form) => form.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  const pattern = new RegExp(`\\b(?:${escaped.join('|')})\\b`, 'g');
  return (text) => {
    const runs: { text: string; elementId: string | null }[] = [];
    let last = 0;
    for (const match of text.matchAll(pattern)) {
      const elementId = forms.get(match[0]) ?? null;
      if (!elementId) continue;
      if (match.index > last) runs.push({ text: text.slice(last, match.index), elementId: null });
      runs.push({ text: match[0], elementId });
      last = match.index + match[0].length;
    }
    if (last < text.length) runs.push({ text: text.slice(last), elementId: null });
    return runs;
  };
}

/** A paragraph's ProseMirror inline content: text runs, italics, line breaks, element links. */
function inlineContent(encoded: string, linker?: EntityLinker): ProseNode[] {
  const nodes: ProseNode[] = [];
  encoded.split('*').forEach((segment, index) => {
    const italic = index % 2 === 1;
    segment.split('\n').forEach((line, lineIndex) => {
      if (lineIndex > 0) nodes.push({ type: 'hardBreak' });
      for (const run of line ? (linker ? linker(line) : [{ text: line, elementId: null }]) : []) {
        const marks = [
          ...(italic ? [{ type: 'italic' }] : []),
          ...(run.elementId
            ? [{ type: 'entityLink', attrs: { targetKind: 'element', targetId: run.elementId, targetBlockId: null } }]
            : []),
        ];
        nodes.push({ type: 'text', text: run.text, ...(marks.length ? { marks } : {}) });
      }
    });
  });
  return nodes;
}

/** The paragraph's ProseMirror `textContent`: no markers, line breaks add no text. */
export function paragraphText(encoded: string): string {
  return encoded.replace(/[*\n]/g, '');
}

export interface ProseBlockLayout {
  id: string;
  kind: 'paragraph' | 'blockquote';
  /** ProseMirror textContent of the top-level block. */
  text: string;
  /** Document position just inside the block (where its text starts). */
  docStart: number;
  /** True when the paragraph contains a hard break. */
  hasBreak: boolean;
}

export interface ProseDocument {
  contentJson: string;
  blocks: ProseBlockLayout[];
}

function nodeSize(node: ProseNode): number {
  if (node.type === 'text') return (node.text as string).length;
  if (node.type === 'hardBreak') return 1;
  return 2 + ((node.content as ProseNode[] | undefined) ?? []).reduce((sum, child) => sum + nodeSize(child), 0);
}

/**
 * A ProseMirror document in the prose editor's schema with a stable id on every
 * block, as the editor itself would leave it. Top-level blocks are laid out so
 * comments and patches can anchor to exact text.
 */
export function buildProseDocument(
  blocks: readonly BookBlock[],
  newId: () => string,
  linker?: EntityLinker,
): ProseDocument {
  const content: ProseNode[] = [];
  const layout: ProseBlockLayout[] = [];
  let position = 0;
  for (const block of blocks) {
    const paragraphs = typeof block === 'string' ? [block] : block;
    const nodes = paragraphs.map((paragraph) => ({ type: 'paragraph', attrs: { id: newId() }, content: inlineContent(paragraph, linker) }));
    const node = typeof block === 'string' ? nodes[0] : { type: 'blockquote', attrs: { id: newId() }, content: nodes };
    content.push(node);
    layout.push({
      id: (node.attrs as { id: string }).id,
      kind: typeof block === 'string' ? 'paragraph' : 'blockquote',
      text: paragraphs.map(paragraphText).join(''),
      docStart: position + 1,
      hasBreak: paragraphs.some((paragraph) => paragraph.includes('\n')),
    });
    position += nodeSize(node);
  }
  return { contentJson: JSON.stringify({ type: 'doc', content }), blocks: layout };
}

export interface TextAnchor {
  blockId: string;
  blockText: string;
  from: number;
  to: number;
  docFrom: number;
  docTo: number;
  text: string;
}

/**
 * Locate a quotation inside one top-level paragraph, as an author's text
 * selection would: it must occur exactly once in the document.
 */
export function anchorQuotation(document: ProseDocument, quotation: string): TextAnchor {
  const hits = document.blocks.flatMap((block) => {
    const found: TextAnchor[] = [];
    for (let offset = block.text.indexOf(quotation); offset >= 0; offset = block.text.indexOf(quotation, offset + 1)) {
      found.push({
        blockId: block.id,
        blockText: block.text,
        from: offset,
        to: offset + quotation.length,
        docFrom: block.docStart + offset,
        docTo: block.docStart + offset + quotation.length,
        text: quotation,
      });
    }
    return found.length && (block.kind !== 'paragraph' || block.hasBreak) ? [null] : found;
  });
  if (hits.length !== 1 || !hits[0]) {
    throw new Error(`Sample quotation must occur once in a plain paragraph: “${quotation}”`);
  }
  return hits[0];
}
